import sys
input = sys.stdin.readline
t = int(input())
for _ in range(t):
	n = int(input())
	c = dict()
	for i in range(n):
		(a, b) = map(int, input().split())
		if a + b in c:
			c[a + b] += 1
		else:
			c[a + b] = 1
	fl = 1
	for i in range(2, n + 1):
		if i in c:
			if c[i] == i - 1:
				fl = 0
				break
	j = n + 1
	k = n
	for i in range(n - 1):
		if j in c:
			if c[j] == k:
				fl = 0
				break
		j += 1
		k -= 1
	if fl == 0:
		print('NO')
	else:
		print('YES')
